def make_step(cid,row,extension,seq,diagnostic):
 (tz,te),(az,ae),(fz,fe),(bz,be)=row; ez,ee=extension
 other_bad,other_bad_en=LESSONS[cid][((seq-1)//2+1)%12][3]
 stepid=f'{cid}-v8-{seq:02}'
 if not diagnostic:
  title,titleen=tz+'：建立模型',te+': construct and analyze'
  obj,objen='用可檢查的成果說明「'+fz+'」。','Demonstrate the following with inspectable work: '+fe+'.'
  ins=az+'。先標出輸入、輸出與適用假設；依圖形、計算或比較表完成推理；把估算、來源事實與待量測項分開。所有自行設定數值均標為教學假設。'
  insen=ae+'. Mark inputs, outputs and assumptions; complete the diagram, calculation or comparison; separate estimates, source facts and measurements still needed. Label all chosen values as hypothetical.'
  kz=['機制：'+fz+'。','模型邊界：不可由目前成果直接推出「'+bz+'」。']
  ke=['Mechanism: '+fe+'.','Model boundary: the current result does not establish the following claim: '+be+'.']
  check='提交「'+tz+'」的圖表或計算、單位與至少一項假設；成果須能追溯到本步指定的輸入和输出，並說明：'+fz+'。'
  checken='Submit the '+te+' diagram/table or calculation with units and at least one assumption, tracing inputs to outputs and explaining: '+fe+'.'
  q='關於「'+tz+'」，哪項推論有物理依據？'; qen='For '+te+', which inference has a physical basis?'
  opts=[fz,bz,other_bad]; opten=[fe,be,other_bad_en]
 else:
  title,titleen=tz+'：故障判讀與驗證',te+': diagnose and verify'
  obj,objen='以新增對照檢查「'+bz+'」這項錯誤主張。','Test the faulty claim: '+be+'.'
  ins='接續前一步「'+tz+'」成果，先指出錯誤主張「'+bz+'」漏掉哪個條件。新增診斷原理：'+ez+'。據此設計一組正常與異常對照；指定可區分兩者的觀察量、取樣位置或時間；寫下證據不足時應保留的未決結論。不得虛構實測數字。'
