result=dict(courses=courses,sources=list(SOURCES.values()),places=places,media=[],related=[],scope='Group C: 33 bilingual courses, each 12 original technical decisions expanded into paired modeling and diagnostic work packages and one explicit hypothetical worked example; external related records are merged by the release integrator.')
